        assert.deepEqual(await commitBatch(dir, B), final);
      } else {
        const C = { id: 'c', entries: [{ key: 'cash', delta: 100 }] };
        const s = await commitBatch(dir, C);
        assert.equal(s.balances.cash - 100 + (s.receipts.some(r => r.id === 'b') ? 0 : 3), 8);
        assert.equal(s.revision, s.receipts.length);
      }
      await assert.rejects(fs.access(path.join(dir, 'pending.json')));
      await fs.access(path.join(dir, 'unrelated.txt'));
      await fs.rm(dir, { recursive: true });
      runs++;
    }
  }
}

for (const phase of ['prepared', 'published', 'complete']) {
  for (const retry of ['recover', 'commitSame', 'commitConflict']) {
    const dir = await fs.mkdtemp(path.join(os.tmpdir(), 'smoke-'));
    await commitBatch(dir, A);
    const err = new Error('stop');
    const seen = [];
    await assert.rejects(commitBatch(dir, B, { checkpoint: async p => { seen.push(p); if (p === phase) throw err; } }), e => e === err);
    if (retry === 'recover') { assert.deepEqual(await recoverLedger(dir), final); assert.deepEqual(await recoverLedger(dir), final); }
    else if (retry === 'commitSame') assert.deepEqual(await commitBatch(dir, B), final);
    else await assert.rejects(commitBatch(dir, { id: 'b', entries: [] }), { code: 'ERR_BATCH_CONFLICT' });
    assert.deepEqual(await recoverLedger(dir), final);
    await fs.rm(dir, { recursive: true });
    runs++;
  }
}

